    {
      "id": "A1",
      "type": "text_present",
      "value": "Expense reports",
      "description": "The Reports section, which holds the period-scoped expense-line export, is open"
    },
    {
      "id": "A2",
      "type": "element_present",
      "value": "Download CSV",
      "description": "The period export control is available next to the Period selector for the requested reporting period"
    },
    {
      "id": "A3",
      "type": "element_present",
      "value": "Period",
      "description": "The Period selector that scopes the export to the requested YYYY-MM is still present"
    },
    {
      "id": "A4",
      "type": "unverifiable",
      "description": "The written report file contains exactly the required keys with correct values: period equal to the requested YYYY-MM; claim_ids and claim_count covering exactly the approved claims of that period (drafts and unapproved claims excluded); by_cost_center holding each counted cost center's summed line amount; and grand_total equal to the sum of the counted line amounts and to the sum of by_cost_center. Page-text predicates cannot read a workspace file, so the deliverable content cannot be checked here."
    }
  ]
}

